.container {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 3rem 1rem;
  background-color: #d6e6f3;

  .authWrapper {
    display: grid;
    grid-template-columns: minmax(0, 1.1fr) minmax(0, 1.1fr);
    gap: 2.5rem;
    align-items: center;
    max-width: 1000px;
    width: 100%;
    background: #ffffff;
    border-radius: 24px;
    box-shadow: 0 18px 45px rgba(15, 23, 42, 0.12);
    padding: 2.25rem;
    margin: 0 auto;
  }

  .msg{
    display: none;
  }

  .box {
    background: linear-gradient(145deg, #01796f, #4ea199);
    padding: 1.75rem;
    border-radius: 18px;
    position: relative;
    overflow: visible;
    text-align: left;
    color: #f9fafb;

    h1 {
      margin-bottom: 1.5rem;
      color: rgba(241, 245, 249, 0.9);
      font-size: 2rem;
      font-weight: 600;
      text-align: left;
    }

    form {
      display: flex;
      flex-direction: column;
      position: relative;
      overflow: visible;

      .fieldGroup {
        display: flex;
        flex-direction: column;
        gap: 0.45rem;
        margin: 0.5rem 0;
        text-align: left;

        label {
          font-size: 0.9rem;
          font-weight: 500;
          color: rgba(226, 232, 240, 0.95);
          text-align: left;
        }
      }

      input {
        margin: 0;
        padding: 0.75rem 1.1rem;
        font-size: 0.95rem;
        border-radius: 999px;
        border: 1px solid rgba(148, 163, 184, 0.5);
        outline: none;
        color: #0f172a;
        background: rgba(241, 245, 249, 0.9);
        text-align: left;
        transition: border-color 0.18s ease, box-shadow 0.18s ease,
          background-color 0.18s ease;

        &::placeholder {
          color: rgba(100, 116, 139, 0.8);
          text-align: left;
        }

        &:focus {
          border-color: #a3e635;
          box-shadow: 0 0 0 1px rgba(163, 230, 53, 0.55);
          background-color: #f9fafb;
        }
      }

      button {
        margin-top: 0.75rem;
        background: linear-gradient(135deg, #bef264, #a3e635);
        color: #052e16;
        padding: 0.8rem 1.6rem;
        border: none;
        border-radius: 999px;
        cursor: pointer;
        font-size: 0.95rem;
        font-weight: 600;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 0.5rem;
        transition: transform 0.16s ease, box-shadow 0.16s ease,
          background 0.18s ease;
        box-shadow: 0 14px 30px rgba(22, 163, 74, 0.4);

        &:hover:not(:disabled) {
          transform: translateY(-1px);
          box-shadow: 0 18px 45px rgba(22, 163, 74, 0.5);
          background: linear-gradient(135deg, #d9f99d, #bef264);
        }

        &:disabled {
          opacity: 0.6;
          cursor: not-allowed;
        }

        .buttonArrow {
          font-size: 1rem;
          font-weight: 600;
          line-height: 1;
          display: inline-flex;
          align-items: center;
          justify-content: center;
        }
      }
    }
  }

  .infoPanel {
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 1.2rem;
    padding-inline: 0.25rem;
  }

  .badge {
    align-self: flex-start;
    padding: 0.3rem 0.9rem;
    border-radius: 999px;
    border: 1px solid rgba(148, 163, 184, 0.6);
    font-size: 0.78rem;
    font-weight: 500;
    color: #475569;
    background: rgba(241, 245, 249, 0.9);
  }

  .heading {
    font-size: 2rem;
    font-weight: 700;
    color: #0f172a;
    letter-spacing: -0.03em;
    margin: 0;
  }

  .highlight {
    color: #01796f;
  }

  .subtext {
    font-size: 0.95rem;
    color: #475569;
    max-width: 26rem;
    line-height: 1.6;
  }

  .infoList {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    font-size: 0.9rem;
    color: #0f172a;
  }

  .infoItem {
    margin: 0;
  }
}


